// Generated by scripts/package.py. Edit the JSON files, then regenerate.
window.ENGLISH_WORKBOOK = {"data/lessons.json":{"schemaVersion":1,"title":"Everyday English","lessons":[{"id":"lesson-01","file":"data/lesson-01.json","number":1,"title":"Everyday expressions"},{"id":"lesson-02","file":"data/lesson-02.json","number":2,"title":"Work, people & everyday life"},{"id":"lesson-03","file":"data/lesson-03.json","number":3,"title":"Journeys, directions & decisions"},{"id":"lesson-04","file":"data/lesson-04.json","number":4,"title":"Progress, independence & good bargains"}]},"data/lesson-01.json":{"schemaVersion":1,"id":"lesson-01","contentVersion":1,"number":1,"title":"Everyday expressions","subtitle":"A journey, a summer job, and a dinner out.","source":{"file":"1 Illustrated_Everyday_Expressions_with_Stories_2.pdf","lesson":1,"pdfPages":[1,2,3,4,5,6],"printedExercisePages":[11,12],"answerKey":"Answers inferred from context; no published answer key is present in the supplied PDF.","transcription":"Obvious OCR errors and line-break hyphenation corrected. Exercise wording and option order retained. Story paragraph 6 is split for readability."},"expressions":[{"id":"be-composed-of","phrase":"be composed of","meaning":"comprise; be made of","examples":["The class was composed of students from the US, Canada, and England.","Water is composed of hydrogen and oxygen."],"dialogue":["A: That's a very interesting sculpture.","B: Yes, it's composed of wood, glass, and old shoes."]},{"id":"clean-off","phrase":"clean off","meaning":"clear; take everything off","examples":["You should clean off your desk. It's very dirty.","He cleaned off the shelf so that his new roommate could use it."],"dialogue":["A: When is dinner?","B: In a few minutes. Please help me clean off the table."]},{"id":"come-across","phrase":"come across","meaning":"find by chance","examples":["I came across some old photographs at my parent's house.","She came across her favorite singer's latest album at the record store."],"dialogue":["A: Please check my homework.","B: Sure. If I come across any mistakes, I'll tell you."]},{"id":"dress-up","phrase":"dress up","meaning":"wear fancy clothes for a special occasion","examples":["Many children dress up as ghosts and monsters on Halloween.","Do I need to dress up for dinner at your parent's house?"],"dialogue":["A: Why did you buy that suit?","B: I want to dress up for the party."]},{"id":"fall-asleep","phrase":"fall asleep","meaning":"go to sleep","examples":["Don't fall asleep when you are driving!","He falls asleep in class almost every day."],"dialogue":["A: You look really tired.","B: I couldn't fall asleep last night."]},{"id":"fill-out","phrase":"fill out","meaning":"write all of the information needed on a form or application","examples":["Everyone has to fill out a customs form when they enter a country.","Can you help me fill out this form? I don't understand it."],"dialogue":["A: I'd like to apply for a credit card.","B: OK. Just fill out this form and sign it."]},{"id":"in-retrospect","phrase":"in retrospect","meaning":"looking back at the past","examples":["In retrospect, I should have studied harder in high school.","You can see all of your past mistakes easily in retrospect."],"dialogue":["A: Wow, I am so full!","B: Me, too. In retrospect, we should have ordered only one pizza."]},{"id":"on-the-whole","phrase":"on the whole","meaning":"in general; all things considered","examples":["On the whole, I enjoyed my time in the United States.","Although there were some slow parts, on the whole the movie was good."],"dialogue":["A: What did you think of the test?","B: On the whole, I felt it was quite easy."]},{"id":"set-out","phrase":"set out","meaning":"leave; begin a journey","examples":["He set out for the market early in the morning.","She packed everything in her car and set out for California."],"dialogue":["A: Did Bob leave already?","B: Yeah, he set out early this morning."]},{"id":"wait-on","phrase":"wait on","meaning":"serve someone in a restaurant","examples":["The man who waited on us last night had a French accent.","How many tables can you wait on at the same time?"],"dialogue":["A: Excuse me, no one has waited on us yet.","B: I am very sorry. I'll get a waiter right away."]}],"practice":{"title":"Choose the best answer","sourcePdfPage":4,"questions":[{"id":"p1","prompt":"____, the university has a very good library and computer center.","options":["Come across","In retrospect","On the whole"],"answer":"On the whole","expressionId":"on-the-whole","explanation":"“On the whole” introduces a general opinion about the university."},{"id":"p2","prompt":"At first, the band ____ a keyboard player, a guitarist, and a singer, but they added a drummer and bassist later.","options":["was composed of","dressed up","waited on"],"answer":"was composed of","expressionId":"be-composed-of","explanation":"“Was composed of” describes the people who made up the band."},{"id":"p3","prompt":"He could see ____ that he should never have told her about his family.","options":["be composed of","fill out","in retrospect"],"answer":"in retrospect","expressionId":"in-retrospect","explanation":"He is looking back at something he did in the past."},{"id":"p4","prompt":"Here is the menu. Someone will be here to ____ you in a few minutes.","options":["come across","set out","wait on"],"answer":"wait on","expressionId":"wait-on","explanation":"A restaurant worker will serve the customer."},{"id":"p5","prompt":"I planned to do my homework after the movie last night, but I ____ when I got home.","options":["cleaned off","fell asleep","set out"],"answer":"fell asleep","expressionId":"fall-asleep","explanation":"“Fell asleep” means went to sleep; “fell” is the past tense of “fall.”"},{"id":"p6","prompt":"Let’s ____ for our anniversary and go to an expensive restaurant.","options":["clean off","dress up","fill out"],"answer":"dress up","expressionId":"dress-up","explanation":"An anniversary dinner is a special occasion for wearing fancy clothes."},{"id":"p7","prompt":"Please ____ the table because it is almost time to eat dinner.","options":["clean off","fill out","set out"],"answer":"clean off","expressionId":"clean-off","explanation":"“Clean off” means clear things from the surface of the table."},{"id":"p8","prompt":"She ____ the registration form and gave it to the secretary.","options":["filled out","on the whole","waited on"],"answer":"filled out","expressionId":"fill-out","explanation":"“Filled out” means wrote the required information on the form."},{"id":"p9","prompt":"Where did you ____ this interesting painting?","options":["be composed of","come across","fall asleep"],"answer":"come across","expressionId":"come-across","explanation":"“Come across” means find by chance. After “did,” use the base verb."},{"id":"p10","prompt":"We ____ for my parent's house very early, but didn’t arrive until after midnight.","options":["dressed up","fell asleep","set out"],"answer":"set out","expressionId":"set-out","explanation":"“Set out” means began a journey. The past form of “set” is also “set.”"}]},"dialogue":{"title":"At a fancy restaurant","sourcePdfPage":5,"wordBank":["is composed of","clean off","came across","dress up","on the whole","wait on"],"lines":[{"id":"d1","speaker":"Lucy","text":"Will Arthur ____ us this evening? He's my favorite waiter here.","answer":"wait on","expressionId":"wait-on","explanation":"Arthur is the waiter who will serve them."},{"id":"d2","speaker":"Sam","text":"I requested him, so he should be our waiter."},{"id":"d3","speaker":"Lucy","text":"Oh my! They didn't ____ this table very well. There is a sticky spot here.","answer":"clean off","expressionId":"clean-off","explanation":"The table was not properly cleared and cleaned."},{"id":"d4","speaker":"Sam","text":"Don't touch it. I'll call someone over to clean it. Excuse me!"},{"id":"d5","speaker":"Waiter","text":"Yes, sir?"},{"id":"d6","speaker":"Sam","text":"My wife ____ a sticky spot on the table. Can you find someone to clean it up for us?","answer":"came across","expressionId":"come-across","explanation":"She found the sticky spot by chance; use the past tense."},{"id":"d7","speaker":"Waiter","text":"Right away."},{"id":"d8","speaker":"Lucy","text":"The staff here ____ such professionals. They are all so polite and efficient.","answer":"is composed of","expressionId":"be-composed-of","explanation":"The staff is made up of professional people."},{"id":"d9","speaker":"Sam","text":"Yes, ____, this is really a first-class restaurant. It is a little expensive, but worth it.","answer":"on the whole","expressionId":"on-the-whole","explanation":"Sam gives his overall opinion of the restaurant."},{"id":"d10","speaker":"Lucy","text":"Look at that man over there! He didn't ____ at all. He is not wearing a tie or a jacket.","answer":"dress up","expressionId":"dress-up","explanation":"The man did not wear fancy clothes for dinner."},{"id":"d11","speaker":"Sam","text":"That's Mel Gibson!"}]},"story":{"title":"Idioms in context","sourcePdfPage":6,"paragraphs":["I go to college in Boston, but my parents now live in Florida. During the summer vacation, I went to visit them. I set out from downtown Boston by bus on Tuesday afternoon. Thursday night, I got off the bus in Florida. I had a lot of trouble falling asleep on the bus, so I was exhausted by the time I arrived at my parents’ house. In retrospect, I probably should have just taken a plane to Florida.","After I was in Florida for a few days, I was well rested again. However, I soon got bored. My friends were all in Boston. I decided to get a job. I came across an advertisement for a job at a local restaurant. I filled out an application and got hired right away.","On the first day of work, I got up early and got ready. I didn’t have to dress up for work, but I did have to wear a uniform. The restaurant made everyone wear a formal white shirt and black shorts. The staff was composed of high school and college students.","At first, there were no customers, but around noon, the restaurant got crowded. I waited on customers and helped clean off tables. On the whole, it was pretty easy work. It wasn’t too busy but it wasn’t too slow either.","As the lunch crowd started to leave, I stopped at a table where an old man and an old woman were sitting. As I was picking up their empty plates, the old man asked me, “Are you from the north?”","I said, “Yes, sir. I’m from Boston. I guess you could tell right away I was from the north, because of the way I speak.”","“Oh no,” the old woman said. “We have never seen legs as white as yours before.”"],"highlights":[{"text":"set out","expressionId":"set-out"},{"text":"falling asleep","expressionId":"fall-asleep"},{"text":"In retrospect","expressionId":"in-retrospect"},{"text":"came across","expressionId":"come-across"},{"text":"filled out","expressionId":"fill-out"},{"text":"dress up","expressionId":"dress-up"},{"text":"was composed of","expressionId":"be-composed-of"},{"text":"waited on","expressionId":"wait-on"},{"text":"clean off","expressionId":"clean-off"},{"text":"On the whole","expressionId":"on-the-whole"}]}},"data/lesson-02.json":{"schemaVersion":1,"id":"lesson-02","contentVersion":1,"number":2,"title":"Work, people & everyday life","subtitle":"Office life, a coffee-shop conversation, and a misplaced purse.","source":{"file":"2 Illustrated_Everyday_Expressions_with_Stories_2.pdf","lesson":2,"pdfPages":[1,2,3,4,5,6],"printedExercisePages":[17,18],"answerKey":"Answers inferred from the lesson definitions and exercise context; no published answer key is present in the supplied PDF.","transcription":"Obvious OCR errors and line-break hyphenation corrected. Exercise wording and option order retained, including the “turn up” distractor in practice question 4. Typographic quotation marks normalized for readability. The story retains the four numbered source paragraphs."},"expressions":[{"id":"be-crazy-about","phrase":"be crazy about","meaning":"like or enjoy in an extreme way","examples":["She is crazy about tennis. She plays every day.","My brother is crazy about movies. He spends all of his money going to see them."],"dialogue":["A: I love buying new clothes.","B: Me, too. I'm crazy about shopping!"]},{"id":"call-it-a-day","phrase":"call it a day","meaning":"stop working","examples":["Let's call it a day!","Bill, you've been here for 10 hours! You should call it a day and go home."],"dialogue":["A: It's 7:30. Let's call it a day.","B: Good idea. See you tomorrow."]},{"id":"concentrate-on","phrase":"concentrate on","meaning":"focus attention toward","examples":["It's too noisy here. I can't concentrate on my homework.","He had to concentrate on the song to hear the words."],"dialogue":["A: Just concentrate on hitting the ball.","B: OK, coach."]},{"id":"get-along-with","phrase":"get along with","meaning":"be friendly with; live or work well together","examples":["Everyone in my family gets along well with each other.","She does not get along with her mother-in-law."],"dialogue":["A: Why aren't you going to Beth's party?","B: I don't get along with her."]},{"id":"have-a-point","phrase":"have a point","meaning":"said when you agree with someone's opinion","examples":["My sister says that I need to spend more time with my family. She has a point.","“That girl only seems stuck-up because she is shy.” “You have a point there.”"],"dialogue":["A: The blue shirt looks better, but it's more expensive.","B: You have a point."]},{"id":"more-often-than-not","phrase":"more often than not","meaning":"usually","examples":["More often than not, he spends his holidays with his parents.","She works late more often than not."],"dialogue":["A: We'd better take an umbrella.","B: Right. It rains more often than not this time of year."]},{"id":"never-mind","phrase":"never mind","meaning":"forget; pay no attention to","examples":["Never mind the car's color. It runs great!","Didn't you wash the dishes yet? Never mind. I'll do them myself!"],"dialogue":["A: Sorry, we don't have leather bags.","B: Never mind. I'll look in another store."]},{"id":"take-a-look-at","phrase":"take a look at","meaning":"look at to evaluate","examples":["The doctor took a look at her foot to see if it was broken.","Please take a look at my essay and let me know what you think of it."],"dialogue":["A: Something's wrong with the car.","B: I'll take a look at it after lunch."]},{"id":"turn-out","phrase":"turn out","meaning":"finally be; end up","examples":["The weather looked bad this morning, but it turned out to be a nice day.","He tried to cook a special dinner for his girlfriend, but it didn't turn out well."],"dialogue":["A: Good luck with your new project.","B: Thanks! I'll let you know how it turns out."]},{"id":"wrap-up","phrase":"wrap up","meaning":"finish; bring to an end","examples":["The senator wrapped up his speech by quoting the president.","The party wrapped up around 3 a.m. after the beer ran out."],"dialogue":["A: It's almost lunchtime.","B: OK. Let's wrap up and go out to eat."]}],"practice":{"title":"Choose the best answer","sourcePdfPage":4,"questions":[{"id":"p1","prompt":"____ I have to sleep with my bedroom window open because our air conditioner doesn't work very well.","options":["Never mind","Get along with","More often than not"],"answer":"More often than not","expressionId":"more-often-than-not","explanation":"“More often than not” means usually. It describes how frequently the speaker sleeps with the window open."},{"id":"p2","prompt":"He ____ his step-brother.","options":["has a point","gets along well with","turns out"],"answer":"gets along well with","expressionId":"get-along-with","explanation":"“Gets along well with” means has a friendly relationship with someone. “Gets” agrees with “he.”"},{"id":"p3","prompt":"I ____ music, especially dance music.","options":["get along with","take a look at","am crazy about"],"answer":"am crazy about","expressionId":"be-crazy-about","explanation":"“Am crazy about” means really like or enjoy something. Use “am” with “I.”"},{"id":"p4","prompt":"We did a lot. Let's ____ and get some rest.","options":["call it a day","never mind","turn up"],"answer":"call it a day","expressionId":"call-it-a-day","explanation":"“Call it a day” means stop working. They have done a lot and want to rest."},{"id":"p5","prompt":"It's lunchtime. Let's ____ this meeting and go out to eat.","options":["concentrate on","have a point","wrap up"],"answer":"wrap up","expressionId":"wrap-up","explanation":"“Wrap up” means finish or bring to an end. They want to finish the meeting before lunch."},{"id":"p6","prompt":"My father wants to have someone ____ our car engine.","options":["get along with","take a look at","wrap up"],"answer":"take a look at","expressionId":"take-a-look-at","explanation":"“Take a look at” means examine or evaluate something. Someone will examine the engine."},{"id":"p7","prompt":"She was too tired to ____ her reading, so she went to bed.","options":["concentrate on","have a point","turn out"],"answer":"concentrate on","expressionId":"concentrate-on","explanation":"“Concentrate on” means focus attention on something. She was too tired to focus on her reading."},{"id":"p8","prompt":"Things will ____ well in the end. You just have to be patient.","options":["take a look at","turn out","call it a day"],"answer":"turn out","expressionId":"turn-out","explanation":"“Turn out” describes the final result. The speaker expects things to end well."},{"id":"p9","prompt":"She said that a good education begins at home. She ____.","options":["concentrated on","gets along with","has a point"],"answer":"has a point","expressionId":"have-a-point","explanation":"“Has a point” means her opinion is reasonable or worth agreeing with."},{"id":"p10","prompt":"Can you help me with this? ____. I see you are busy.","options":["Take a look","Never mind","Wrap up"],"answer":"Never mind","expressionId":"never-mind","explanation":"“Never mind” withdraws the request for help after the speaker notices that the other person is busy."}]},"dialogue":{"title":"At a coffee shop","sourcePdfPage":5,"wordBank":["never mind","am not crazy about","got along with","have a point","take a look at","turn out"],"lines":[{"id":"d1","speaker":"Alice","text":"How did your date last night ____?","answer":"turn out","expressionId":"turn-out","explanation":"Alice asks about the result of the date. After “did,” use the base form “turn out.”"},{"id":"d2","speaker":"Carol","text":"It was O.K. We ____ each other, but I didn't feel any attraction for him.","answer":"got along with","expressionId":"get-along-with","explanation":"They were friendly and comfortable together. “Got” is the past tense of “get.”"},{"id":"d3","speaker":"Alice","text":"What do you mean?"},{"id":"d4","speaker":"Carol","text":"He was a nice guy, but not my type. I ____ a man who spends his whole day with a computer. I prefer someone who is more of a “people person.”","answer":"am not crazy about","expressionId":"be-crazy-about","explanation":"Carol does not particularly like that type of man. The negative phrase fits her stated preference."},{"id":"d5","speaker":"Alice","text":"Computer programmers make a lot of money, Carol."},{"id":"d6","speaker":"Carol","text":"You ____, Alice. Actually, he does work for a very large company.","answer":"have a point","expressionId":"have-a-point","explanation":"Carol agrees that Alice has offered a reasonable opinion."},{"id":"d7","speaker":"Alice","text":"Is he handsome?"},{"id":"d8","speaker":"Carol","text":"We took a picture together at one of those funny photo booths. Here, ____ him for yourself.","answer":"take a look at","expressionId":"take-a-look-at","explanation":"Carol invites Alice to look at the photo and form her own opinion."},{"id":"d9","speaker":"Alice","text":"That's him? Oh, ____, Carol. You can do better than that!","answer":"never mind","expressionId":"never-mind","explanation":"Alice drops the earlier favorable suggestion after seeing the photo."}]},"story":{"title":"Idioms in context","sourcePdfPage":6,"paragraphs":["I usually get along with everyone at my office. Recently however, the woman who sits across from me bought a new cell phone. She was crazy about it. More often than not, she was chatting with her friends. It was very difficult to concentrate on work. One afternoon, we all decided to call it a day and go out for dinner. However, we made the woman promise not to bring her cell phone into the restaurant. “Do you think you’ll survive without it?” I joked to her. “No problem,” she said.","The evening was fun but it was getting late so we wrapped up dinner and left the restaurant. I was the last to leave and just as I was getting into my car, a waiter came running up to me. “I found this purse at your table!” he said. I took a look at it. “That’s my co-worker’s purse,” I said. “Why don’t you call and leave a message on her answering machine,” the waiter suggested. “You can use the phone in the restaurant.”","We went inside. I was about to dial her home number when I had an idea. “Never mind leaving a message on her machine. I’ll call her cellular phone. That way, she can drive back before she gets all the way home.” “You have a good point!” the waiter said.","When I called her cellular phone, a ringing noise came from her purse. It turned out that her phone was in her purse the whole time!"],"highlights":[{"text":"get along with","expressionId":"get-along-with"},{"text":"was crazy about","expressionId":"be-crazy-about"},{"text":"More often than not","expressionId":"more-often-than-not"},{"text":"concentrate on","expressionId":"concentrate-on"},{"text":"call it a day","expressionId":"call-it-a-day"},{"text":"wrapped up","expressionId":"wrap-up"},{"text":"took a look at","expressionId":"take-a-look-at"},{"text":"Never mind","expressionId":"never-mind"},{"text":"have a good point","expressionId":"have-a-point"},{"text":"turned out","expressionId":"turn-out"}]}},"data/lesson-03.json":{"schemaVersion":1,"id":"lesson-03","contentVersion":1,"number":3,"title":"Journeys, directions & decisions","subtitle":"A highway conversation, a wrong turn, and a country picnic.","source":{"file":"3 Illustrated_Everyday_Expressions_with_Stories_2.pdf","lesson":3,"pdfPages":[1,2,3,4,5,6],"printedExercisePages":[23,24],"answerKey":"Answers inferred from the lesson definitions and exercise context; no published answer key is present in the supplied PDF.","transcription":"Obvious OCR errors and line-break hyphenation corrected. Exercise wording and option order retained. Typographic quotation marks normalized for readability. Tom's long dialogue turn is split between two consecutive entries so each entry contains one blank. The story retains the three numbered source paragraphs."},"expressions":[{"id":"bring-up","phrase":"bring up","meaning":"start to talk about something","examples":["I hate to bring this up, but you have some food between your teeth.","When my mother is mad at me she always brings up the time I forgot her birthday."],"dialogue":["A: I really don't like the new coffee machine.","B: You should bring it up at the next staff meeting."]},{"id":"by-all-means","phrase":"by all means","meaning":"said to encourage a person to do something","examples":["“May I have some more chicken?” “By all means!”","By all means, take your time and look around the store."],"dialogue":["A: Could I borrow your pen?","B: By all means!"]},{"id":"by-chance","phrase":"by chance","meaning":"not planned; luckily","examples":["By chance, the first birthday card she read was from her brother.","They met by chance while they were both vacationing in Hawaii."],"dialogue":["A: Where did you get your cat?","B: I found him by chance in the park."]},{"id":"carry-on","phrase":"carry on","meaning":"continue","examples":["After the storm passed, we carried on painting the house.","When the announcement was finished, the class carried on with the lesson."],"dialogue":["A: Is everyone back from lunch?","B: Yes. Let's carry on with the meeting."]},{"id":"draw-the-line-at","phrase":"draw the line at","meaning":"say some point is the limit","examples":["My parents let me use the car, but they draw the line at allowing me to take long trips.","I don't mind sharing a room, but I draw the line at sleeping in the same bed."],"dialogue":["A: Let's go to a nightclub.","B: OK, but I draw the line at doing disco!"]},{"id":"fix-up","phrase":"fix up","meaning":"repair; make nice or good again","examples":["They fixed up the office by putting in new carpet and painting the walls.","It would cost more to fix up this old boat than to buy a new one."],"dialogue":["A: Is John going to buy a new house?","B: No, he's going to fix up his old one."]},{"id":"get-lost","phrase":"get lost","meaning":"become confused about one's location","examples":["We got lost on the way to the theater.","The directions were not clear, so we got lost."],"dialogue":["A: Why are you late?","B: I got lost on the way."]},{"id":"high-time","phrase":"high time","meaning":"time for some action that has been postponed too long","examples":["I think it's high time we fix the heater. I'm freezing!","My mother said it was high time that I got my hair cut and found a job."],"dialogue":["A: It's high time you cleaned your room!","B: Yes, Mom. I'll do it right away."]},{"id":"lose-ones-temper","phrase":"lose one's temper","meaning":"become angry","examples":["He lost his temper and hit the table with his fist.","It is dangerous to lose your temper while driving."],"dialogue":["A: What happened to your hand?","B: I lost my temper and punched the wall!"]},{"id":"pull-over","phrase":"pull over","meaning":"move one's vehicle to the side of the road and stop","examples":["She pulled over to take a picture of the beautiful scenery by the highway.","The police officer yelled at the driver, “Pull over!”"],"dialogue":["A: I think we're lost.","B: Let's pull over and look at the map again."]}],"practice":{"title":"Choose the best answer","sourcePdfPage":4,"questions":[{"id":"p1","prompt":"After a short coffee break we ____ with the meeting.","options":["carried on","fixed up","pulled over"],"answer":"carried on","expressionId":"carry-on","explanation":"“Carried on” means continued. The meeting resumed after the break."},{"id":"p2","prompt":"I hate to ____ this subject now, but do you have the money you owe me?","options":["bring up","carry on","get lost"],"answer":"bring up","expressionId":"bring-up","explanation":"“Bring up” means introduce a topic into a conversation. The speaker introduces the subject of the debt."},{"id":"p3","prompt":"If you are tired, ____ take a nap on my bed.","options":["by chance","high time","by all means"],"answer":"by all means","expressionId":"by-all-means","explanation":"“By all means” gives permission or encouragement. The speaker welcomes the other person to take a nap."},{"id":"p4","prompt":"My uncle is generous, but he ____ lending money to relatives.","options":["by all means","draws the line at","high time"],"answer":"draws the line at","expressionId":"draw-the-line-at","explanation":"“Draws the line at” sets a limit. He is generous but will not lend money to relatives."},{"id":"p5","prompt":"She can be very scary when she ____.","options":["gets lost","carries on","loses her temper"],"answer":"loses her temper","expressionId":"lose-ones-temper","explanation":"“Loses her temper” means becomes angry. Her anger can frighten people."},{"id":"p6","prompt":"____, I found ten dollars under the table at the restaurant.","options":["Draw the line at","By chance","High time"],"answer":"By chance","expressionId":"by-chance","explanation":"“By chance” means accidentally or without planning. Finding the money was unexpected."},{"id":"p7","prompt":"The bus driver ____ because one of the passengers got sick.","options":["pulled over","fixed up","got lost"],"answer":"pulled over","expressionId":"pull-over","explanation":"“Pulled over” means moved the vehicle to the side of the road and stopped."},{"id":"p8","prompt":"They wanted to ____ the old apartment, but they did not have enough money.","options":["lose his temper","fix up","carry on"],"answer":"fix up","expressionId":"fix-up","explanation":"“Fix up” means repair or improve something. They wanted to renovate the apartment."},{"id":"p9","prompt":"We ____ in London and drove around for hours in the fog.","options":["fixed up","brought up","got lost"],"answer":"got lost","expressionId":"get-lost","explanation":"“Got lost” means became unsure of the way. They could not find their destination."},{"id":"p10","prompt":"He was surprised when his boss told him, “I think it’s ____ you got a raise.”","options":["high time","draw the line at","by chance"],"answer":"high time","expressionId":"high-time","explanation":"“High time” means an action is overdue. The boss thinks the employee should already have received a raise."}]},"dialogue":{"title":"On the highway","sourcePdfPage":5,"wordBank":["by all means","by chance","carry on","got lost","high time","pull over"],"lines":[{"id":"d1","speaker":"Tom","text":"Yes, Officer?"},{"id":"d2","speaker":"Policeman","text":"I asked you to ____ because your brake light is broken. May I see your license and car registration?","answer":"pull over","expressionId":"pull-over","explanation":"The policeman asked Tom to move his vehicle to the side of the road and stop."},{"id":"d3","speaker":"Tom","text":"____! Here they are.","answer":"by all means","expressionId":"by-all-means","explanation":"Tom willingly agrees to show the requested documents."},{"id":"d4","speaker":"Policeman","text":"Well, I think it's ____ you had that fixed. It's not safe to drive around with a broken brake light.","answer":"high time","expressionId":"high-time","explanation":"Repairing the brake light is overdue because driving with it broken is unsafe."},{"id":"d5","speaker":"Tom","text":"Yes, sir."},{"id":"d6","speaker":"Policeman","text":"I won't give you a ticket this time. Get that light fixed."},{"id":"d7","speaker":"Tom","text":"I will, Officer. Um, I wonder if you could help. I met my friend ____ at the post office this morning and we planned to meet at Le Chez for lunch.","answer":"by chance","expressionId":"by-chance","explanation":"Tom met his friend accidentally, without planning the encounter."},{"id":"d8","speaker":"Tom","text":"I thought it was on Lexington Street, but I took a wrong turn and ____.","answer":"got lost","expressionId":"get-lost","explanation":"Taking the wrong turn left Tom unsure of his location."},{"id":"d9","speaker":"Policeman","text":"At the next stoplight, turn left. Lexington will be the third street on the right."},{"id":"d10","speaker":"Tom","text":"Thank you, officer! ____ the good work you are doing!","answer":"carry on","expressionId":"carry-on","explanation":"Tom encourages the policeman to continue doing good work."}]},"story":{"title":"Idioms in context","sourcePdfPage":6,"paragraphs":["Everybody knows that men hate to stop and ask for directions. My husband is no different. Every time we get lost, we drive around for hours before he finally pulls over and asks for help.","One Saturday we saw an ad in the newspaper for a country dance and picnic at a farm outside of town. We fixed up our old cowboy hats, cut out the map from the newspaper and started driving. After a few hours, I brought up the fact that we were lost. Of course my husband lost his temper when I suggested we ask someone for directions. “I can find it!” he yelled. I didn’t see any point in fighting about it, so I just told him, “By all means, carry on.”","After another hour of driving, I decided it was high time to ask for help. By chance we passed a little gas station with an old man sitting out by the pumps. My husband agreed to stop because we needed gas, but he drew the line at asking for directions. I got out of the car and walked over to the old man. Before I asked him anything he smiled and said, “The map is wrong. It’s Highway 23, not 32.” “How did you know?” I asked in surprise. “You’re the fifth woman whose husband has gotten lost in the last hour!”"],"highlights":[{"text":"get lost","expressionId":"get-lost"},{"text":"pulls over","expressionId":"pull-over"},{"text":"fixed up","expressionId":"fix-up"},{"text":"brought up","expressionId":"bring-up"},{"text":"lost his temper","expressionId":"lose-ones-temper"},{"text":"By all means","expressionId":"by-all-means"},{"text":"carry on","expressionId":"carry-on"},{"text":"high time","expressionId":"high-time"},{"text":"By chance","expressionId":"by-chance"},{"text":"drew the line at","expressionId":"draw-the-line-at"}]}},"data/lesson-04.json":{"schemaVersion":1,"id":"lesson-04","contentVersion":1,"number":4,"title":"Progress, independence & good bargains","subtitle":"A hospital visit, learning English, and a jewelry-shopping mix-up.","source":{"file":"4 Illustrated_Everyday_Expressions_with_Stories_2.pdf","lesson":4,"pdfPages":[1,2,3,4,5,6],"printedExercisePages":[29,30],"answerKey":"Answers inferred from the lesson definitions and exercise context; no published answer key is present in the supplied PDF.","transcription":"Obvious OCR errors and line-break hyphenation corrected. Exercise wording and option order retained. Typographic quotation marks normalized for readability. The story retains the five numbered source paragraphs; the final unnumbered closing sentence is included in paragraph 5."},"expressions":[{"id":"a-steal","phrase":"a steal","meaning":"very cheap; a very good price","examples":["My friend sold me his old car. It was a steal!","The land next to the river is a steal! You should buy it."],"dialogue":["A: I just bought a DVD player for $95!","B: Wow! What a steal!"]},{"id":"at-hand","phrase":"at hand","meaning":"near (time or space)","examples":["Christmas is at hand. I have to buy gifts for my family.","When I was a child, my mother was always close at hand."],"dialogue":["A: I fear that war is at hand.","B: Don't worry. I'm sure the countries will reach an agreement."]},{"id":"get-better","phrase":"get better","meaning":"improve","examples":["His cold got better after he took a day off work.","Her singing will get better if she practices every day."],"dialogue":["A: This movie is boring!","B: Don't worry. It gets better."]},{"id":"more-or-less","phrase":"more or less","meaning":"approximately; almost","examples":["My cousin and I are more or less the same age.","The airline tickets were more or less the same price."],"dialogue":["A: Which shirt is better?","B: They are more or less the same quality."]},{"id":"on-hand","phrase":"on hand","meaning":"near and ready for use","examples":["Do you have any bandages on hand? I cut myself.","There is a representative on hand twenty-four hours a day to help customers."],"dialogue":["A: There's going to be five extra people at the party.","B: No problem. We have plenty of food on hand."]},{"id":"on-ones-own","phrase":"on one's own","meaning":"without help from others","examples":["She has lived on her own since she was twenty-two.","He cooked this whole meal on his own without any help from his mother."],"dialogue":["A: Do you need help fixing the sink?","B: No, thanks. I can do it on my own."]},{"id":"refer-to-a-as-b","phrase":"refer to A as B","meaning":"use the name B for A","examples":["He referred to his classmate as his friend even though they only studied together.","Many people refer to this book as the author's greatest work."],"dialogue":["A: What did your teacher say about your paper?","B: He referred to it as the work of a genius!"]},{"id":"take-ones-time","phrase":"take one's time","meaning":"slowly; in a relaxed way","examples":["She took her time and made sure she did not make any mistakes on the test.","He is taking his time getting ready. He wants to look nice."],"dialogue":["A: I'll be there as soon as I can!","B: Take your time. The movie doesn't start until 3:00."]},{"id":"think-highly-of","phrase":"think highly of","meaning":"have a good opinion of","examples":["Her teacher thought highly of her ability to draw.","He doesn't think very highly of his neighbors."],"dialogue":["A: Mr. Henry is such a great teacher!","B: Yes. All the students think highly of him."]},{"id":"try-out","phrase":"try out","meaning":"do or use to see if something works correctly","examples":["Don't buy the bike until you try it out first.","I tried out several software programs, but none of them were good."],"dialogue":["A: Your skateboard looks really fun.","B: It is! Why don't you try it out?"]}],"practice":{"title":"Choose the best answer","sourcePdfPage":4,"questions":[{"id":"p1","prompt":"He often ____ his wife as his best friend.","options":["refers to","tries out","thinks highly of"],"answer":"refers to","expressionId":"refer-to-a-as-b","explanation":"“Refers to A as B” means calls A by the name B. He calls his wife his best friend."},{"id":"p2","prompt":"I want to ____ that new language program for learning English while sleeping.","options":["try out","take my time","get better"],"answer":"try out","expressionId":"try-out","explanation":"“Try out” means test something to see how it works. The speaker wants to test the language program."},{"id":"p3","prompt":"It has been six years, ____, since I visited my hometown.","options":["more or less","at hand","a steal"],"answer":"more or less","expressionId":"more-or-less","explanation":"“More or less” means approximately. The time since the visit is about six years."},{"id":"p4","prompt":"Keep plenty of coffee ____ because this is going to be a long meeting.","options":["more or less","on hand","on your own"],"answer":"on hand","expressionId":"on-hand","explanation":"“On hand” means available and ready for use. Coffee should be ready during the meeting."},{"id":"p5","prompt":"She ____ her supervisor, so she does not mind when he offers her suggestions.","options":["takes her time","thinks highly of","is on her own"],"answer":"thinks highly of","expressionId":"think-highly-of","explanation":"“Thinks highly of” means has a good opinion of. She respects her supervisor and welcomes his suggestions."},{"id":"p6","prompt":"Wherever the president goes, his bodyguards are close ____.","options":["on their own","a steal","at hand"],"answer":"at hand","expressionId":"at-hand","explanation":"“At hand” means nearby. The bodyguards stay close to the president."},{"id":"p7","prompt":"There is no rush, so you can ____ getting ready.","options":["get better","refer to","take your time"],"answer":"take your time","expressionId":"take-ones-time","explanation":"“Take your time” means proceed slowly and without rushing."},{"id":"p8","prompt":"This computer is ____ at this price. You should buy it before the sale finishes.","options":["on hand","a steal","refer to"],"answer":"a steal","expressionId":"a-steal","explanation":"“A steal” means a very good bargain. The sale price is especially low."},{"id":"p9","prompt":"We had to study most of the material ____ because the professor only wanted to talk about his theory in class.","options":["try out","more or less","on our own"],"answer":"on our own","expressionId":"on-ones-own","explanation":"“On our own” means without help. The students had to learn the material independently."},{"id":"p10","prompt":"You will never ____ if you don't rest and do as the doctor says.","options":["think highly of","get better","refer to"],"answer":"get better","expressionId":"get-better","explanation":"“Get better” means improve or recover. Rest and following medical advice help recovery."}]},"dialogue":{"title":"In the hospital","sourcePdfPage":5,"wordBank":["take your time","refer to him as","on my own","more or less","getting better","thinks highly of"],"lines":[{"id":"d1","speaker":"Bob","text":"How are you feeling, Mark?"},{"id":"d2","speaker":"Mark","text":"I think I'm ____. At least I can move my fingers today.","answer":"getting better","expressionId":"get-better","explanation":"Mark is improving physically. Use “getting better” after “I’m.”"},{"id":"d3","speaker":"Bob","text":"Great! Everyone ____ the doctor who is treating you. They say he is the best.","answer":"thinks highly of","expressionId":"think-highly-of","explanation":"Everyone has a good opinion of the doctor. “Everyone” takes the singular verb “thinks.”"},{"id":"d4","speaker":"Mark","text":"Yeah. He is good. I heard the nurse ____ Dr. Miracle.","answer":"refer to him as","expressionId":"refer-to-a-as-b","explanation":"The nurse called the doctor “Dr. Miracle.” After “heard the nurse,” the base verb “refer” fits."},{"id":"d5","speaker":"Bob","text":"Well, everyone at work is hoping you can come back soon, but ____. Do you know how long you will be in the hospital?","answer":"take your time","expressionId":"take-ones-time","explanation":"Bob tells Mark not to rush his recovery."},{"id":"d6","speaker":"Mark","text":"Actually, I am going home tomorrow. And since my wife has to work, I'll be ____ there all day.","answer":"on my own","expressionId":"on-ones-own","explanation":"Mark will be alone at home without his wife’s help during the day."},{"id":"d7","speaker":"Bob","text":"Will you be OK?"},{"id":"d8","speaker":"Mark","text":"I think so. I can manage things with my left hand ____.","answer":"more or less","expressionId":"more-or-less","explanation":"“More or less” means approximately or almost. Mark can manage, although perhaps not perfectly."},{"id":"d9","speaker":"Bob","text":"If you need anything, just call. I'll be close at hand. I'll come over and give you a hand. Just hand over all your problems to me. I can handle them. I'll be on hand."},{"id":"d10","speaker":"Mark","text":"OK! OK! I get it. Very funny! Thanks, Bob!"}]},"story":{"title":"Idioms in context","sourcePdfPage":6,"paragraphs":["My Brazilian friend has only lived in the United States for six months, but his English is great. Before he came to the US, he studied in a language school, but mostly he learned English on his own from reading English books and watching movies. He had learned basic conversation before he arrived in the US. Then, after he got here, his vocabulary and listening got better very quickly. I would say that he is now more or less fluent in English. However, sometimes he still has trouble with idioms.","One day, he asked me to help him buy some jewelry for his girlfriend back in Brazil. Her birthday was close at hand and he wanted to get something nice. He showed me a picture of his girlfriend before we went shopping. When I saw the picture I said, “Wow! Your girlfriend is a real spring chicken.”","My friend asked me, “Why do you refer to my girlfriend as a chicken?” I explained to my friend, “I just mean your girlfriend is very young and beautiful.”","At the jewelry store, they had several very nice necklaces on hand. I suggested that we take our time and look at several stores, but my friend found a diamond necklace that was a steal. He called the saleswoman over to buy it.","As the saleswoman was taking out the necklace, my friend decided to try out the new idiom he learned. He showed the saleswoman the picture of his girlfriend and asked, “Don’t you think she is a chicken noodle?” My friend’s English may not be perfect, but I still think highly of it."],"highlights":[{"text":"on his own","expressionId":"on-ones-own"},{"text":"got better","expressionId":"get-better"},{"text":"more or less","expressionId":"more-or-less"},{"text":"at hand","expressionId":"at-hand"},{"text":"refer to my girlfriend as","expressionId":"refer-to-a-as-b"},{"text":"on hand","expressionId":"on-hand"},{"text":"take our time","expressionId":"take-ones-time"},{"text":"a steal","expressionId":"a-steal"},{"text":"try out","expressionId":"try-out"},{"text":"think highly of","expressionId":"think-highly-of"}]}}};
